  "headline": "Amiodarone hydrochloride is not on FDA's shortage list; both Corvale sites use product from Bryant Ranch Prepack (FEI 1000519407) whose latest inspection was VAI on 2026-07-16",
  "headline_cites": ["D3", "E14", "E12"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include amiodarone hydrochloride as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale East holds 144 tablets of the 200 mg presentation, providing 9.8 days of supply at current use.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 268 tablets of the same presentation, providing 17.8 days of supply at current use.",
      "cites": ["D2"]
    },
    {
      "text": "Both sites' inventory is labeled by Bryant Ranch Prepack (FEI 1000519407) per NDC 71335194204.",
      "cites": ["E1", "E2", "E14"]
    },
    {
      "text": "The plant's most recent FDA inspection ended 2026-07-16 and was classified VAI.",
      "cites": ["E12", "E14"]
    },
    {
      "text": "The ranked transfer option moves 57 tablets from Corvale General to Corvale East, leaving General with about two weeks on hand and bringing East to 14 days.",
      "cites": ["D4"]
    },
    {
      "text": "Alternate manufacturers Advagen Pharma Limited and Aurobindo Pharma Limited are not on the shortage list today and their labels name no plant we could place.",
      "cites": ["D5", "D6"]
    }
  ]
}
